from attr import attrs, attrib, validators

@attrs(hash=True)
class A:
    x = attrib(validator=validators.in_([1, 2, 3]))

try:
    hash(A)
    print("A is hashable")
except TypeError as e:
    print(f"A is not hashable: {e}")

@attrs(hash=True)
class B:
    x = attrib(validator=validators.in_({1, 2, 3}))

try:
    hash(B)
    print("B is hashable")
except TypeError as e:
    print(f"B is not hashable: {e}")

